# ============================================================
# Leave-one-out sensitivity analysis
# ============================================================
#
# Purpose:
#   Assess whether the primary MR estimate is disproportionately
#   driven by any single genetic instrument.
#
# Input:
#   Harmonized MR datasets generated by 02_Univariable_MR.
#
# Output:
#   results/sensitivity/leave_one_out_results.csv
#   results/sensitivity/leave_one_out_plots/*.pdf
#
# Important:
#   - The same harmonized MR datasets used for the primary
#     random-effects IVW analyses are used here.
#   - No independent SNP selection is performed.
#   - No LD clumping is performed.
#   - No independent harmonisation is performed.
#   - Each analysis sequentially removes one SNP while retaining
#     all other valid instruments.
#
# Software:
#   R >= 4.5.0
#   TwoSampleMR 0.6.29
#
# ============================================================


# ------------------------------------------------------------
# 1. Packages
# ------------------------------------------------------------

required_packages <- c(
  "here",
  "TwoSampleMR",
  "readr",
  "dplyr",
  "ggplot2"
)

missing_packages <- required_packages[
  !vapply(required_packages, requireNamespace, logical(1), quietly = TRUE)
]

if (length(missing_packages) > 0) {
  stop(
    "The following required packages are not installed: ",
    paste(missing_packages, collapse = ", "),
    call. = FALSE
  )
}

library(here)
library(TwoSampleMR)
library(readr)
library(dplyr)
library(ggplot2)


# ------------------------------------------------------------
# 2. Project directories
# ------------------------------------------------------------

harmonized_dir <- here::here(
  "results",
  "primary_MR",
  "harmonized"
)

output_dir <- here::here(
  "results",
  "sensitivity"
)

plot_dir <- here::here(
  "results",
  "sensitivity",
  "leave_one_out_plots"
)

dir.create(
  output_dir,
  recursive = TRUE,
  showWarnings = FALSE
)

dir.create(
  plot_dir,
  recursive = TRUE,
  showWarnings = FALSE
)


# ------------------------------------------------------------
# 3. Input files
# ------------------------------------------------------------

harmonized_files <- c(
  # "CRP_on_VaD_overall.csv",
  # "CRP_on_VaD_undefined.csv",
  # "CRP_on_VaD_subcortical.csv",
  # "CRP_on_VaD_multi_infarct.csv",
  # "CRP_on_VaD_mixed.csv"
)

if (length(harmonized_files) == 0) {
  stop(
    paste0(
      "No harmonized MR input files have been specified.\n",
      "Please populate 'harmonized_files' with the exact output ",
      "files generated by 02_Univariable_MR."
    ),
    call. = FALSE
  )
}

harmonized_paths <- file.path(
  harmonized_dir,
  harmonized_files
)

missing_files <- harmonized_paths[
  !file.exists(harmonized_paths)
]

if (length(missing_files) > 0) {
  stop(
    "The following harmonized MR input files do not exist:\n",
    paste(missing_files, collapse = "\n"),
    call. = FALSE
  )
}


# ------------------------------------------------------------
# 4. Validate harmonized MR dataset
# ------------------------------------------------------------

validate_harmonized_data <- function(dat, file_name) {
  
  required_columns <- c(
    "SNP",
    "beta.exposure",
    "se.exposure",
    "beta.outcome",
    "se.outcome",
    "mr_keep"
  )
  
  missing_columns <- setdiff(
    required_columns,
    names(dat)
  )
  
  if (length(missing_columns) > 0) {
    stop(
      paste0(
        "Input file '", file_name,
        "' is missing required columns: ",
        paste(missing_columns, collapse = ", ")
      ),
      call. = FALSE
    )
  }
  
  dat <- dat %>%
    filter(
      !is.na(SNP),
      !is.na(beta.exposure),
      !is.na(se.exposure),
      !is.na(beta.outcome),
      !is.na(se.outcome),
      mr_keep == TRUE
    )
  
  if (nrow(dat) < 3) {
    return(NULL)
  }
  
  dat
}


# ------------------------------------------------------------
# 5. Run leave-one-out analysis
# ------------------------------------------------------------

loo_results <- list()

for (i in seq_along(harmonized_paths)) {
  
  input_file <- harmonized_paths[i]
  input_name <- basename(input_file)
  
  message(
    "Processing leave-one-out analysis: ",
    input_name
  )
  
  dat <- readr::read_csv(
    input_file,
    show_col_types = FALSE
  )
  
  dat <- validate_harmonized_data(
    dat = dat,
    file_name = input_name
  )
  
  if (is.null(dat)) {
    message(
      "  Fewer than 3 valid SNPs. Leave-one-out analysis skipped."
    )
    next
  }
  
  message(
    "  Valid SNPs: ",
    nrow(dat)
  )
  
  result <- tryCatch(
    {
      TwoSampleMR::mr_leaveoneout(dat)
    },
    error = function(e) {
      warning(
        "Leave-one-out analysis failed for ",
        input_name,
        ": ",
        conditionMessage(e),
        call. = FALSE
      )
      NULL
    }
  )
  
  if (is.null(result) || nrow(result) == 0) {
    next
  }
  
  result <- result %>%
    mutate(
      input_file = input_name,
      .before = 1
    )
  
  loo_results[[length(loo_results) + 1]] <-
    result
  
  
  # ----------------------------------------------------------
  # Leave-one-out plot
  # ----------------------------------------------------------
  
  plot_result <- tryCatch(
    {
      TwoSampleMR::mr_leaveoneout_plot(result)
    },
    error = function(e) {
      warning(
        "Leave-one-out plot failed for ",
        input_name,
        ": ",
        conditionMessage(e),
        call. = FALSE
      )
      NULL
    }
  )
  
  if (!is.null(plot_result) && length(plot_result) > 0) {
    
    safe_name <- tools::file_path_sans_ext(
      tools::file_path_sans_ext(input_name)
    )
    
    plot_file <- file.path(
      plot_dir,
      paste0(
        safe_name,
        "_leave_one_out.pdf"
      )
    )
    
    ggsave(
      filename = plot_file,
      plot = plot_result[[1]],
      width = 7,
      height = 7,
      units = "in"
    )
  }
}


# ------------------------------------------------------------
# 6. Combine results
# ------------------------------------------------------------

loo_results <- if (
  length(loo_results) > 0
) {
  bind_rows(loo_results)
} else {
  tibble()
}


# ------------------------------------------------------------
# 7. Save numerical results
# ------------------------------------------------------------

output_file <- file.path(
  output_dir,
  "leave_one_out_results.csv"
)

readr::write_csv(
  loo_results,
  output_file,
  na = ""
)


# ------------------------------------------------------------
# 8. Completion message
# ------------------------------------------------------------

message(
  "\nLeave-one-out analysis completed."
)

message(
  "Results saved to: ",
  output_file
)

message(
  "Plots saved to: ",
  plot_dir
)
